};
var CATNAME = {
  h: 'hydrogen', alk: 'alkali metal', alke: 'alkaline earth metal', d: 'transition metal (d-block)',
  pn: 'nonmetal (group 15–16)', hal: 'halogen', nob: 'noble gas', w: 'main-group (p-block)',
  lan: 'lanthanide placeholder', act: 'actinide placeholder'
};

function chargeFill(c) {
  if (c === 'var') return '#ffcb8a';
  if (c === null || c === undefined) return '#f1f1f1';
  if (c === 0) return '#d8d8d8';
  if (c > 0) return ['', '#d3e3ff', '#a2c6ff', '#6fa5ff'][Math.min(c, 3)];
  var a = Math.abs(c);
  return ['', '#ffd8d8', '#ffb6b6', '#ff9191', '#ff6f6f'][Math.min(a, 4)];
}

