/* ---------- layers ---------- */
var rectLayer = ptDraw.group();
var bandLayer = ptDraw.group();
var textLayer = ptDraw.group().attr('pointer-events', 'none');
var annoLayer = ptDraw.group().attr('pointer-events', 'none');

var cells = [];
var state = { group: 1, sweepActive: false, scheme: 'type', region: 'overview', selected: null };

function ruleFor(c) {
  if (c.cat === 'nob') return 'Group 18: a full valence shell means there is no energetic reason to gain or lose electrons, so no common ion forms. Every other charge in the table is measured against these configurations.';
  if (c.g === 1) return 'Group 1: losing the single valence s electron gives a +1 cation with the previous noble-gas core. Charge = group number.';
  if (c.g === 2) return 'Group 2: losing both valence s electrons gives a +2 cation. Charge = group number.';
  if (c.g >= 3 && c.g <= 12) return 'd-block: the 4s electrons leave first, then d electrons, so one metal can show several charges. Group position alone does not predict the ion.';
  if (c.g === 13) return 'Group 13: losing three electrons empties the s and p valence orbitals, giving 3+ (group number − 10).';
  if (c.g === 14) return 'Group 14 sits midway: carbon can in principle gain four electrons to reach neon (C⁴⁻), but these elements normally bond covalently.';
  if (c.g >= 15 && c.g <= 17) return 'Group ' + c.g + ': gaining ' + (18 - c.g) + ' electron' + ((18 - c.g) > 1 ? 's' : '') + ' fills the p subshell and reaches the next noble gas — charge = 18 − group.';
  return 'No single common ionic charge is shown for this element in this table.';
}

function popupBody(c) {
  var ion = c.lines.length ? c.lines.join(' or ') : 'no common ion shown';
  return 'Ion(s): ' + ion + '. Configuration: ' + (c.conf || 'not shown') + '. ' + ruleFor(c);
}

function addCell(g, p, sym, lines, charge, cat, conf) {
  var x = cx(g), y = cy(p);
  var rect = rectLayer.rect(CW, CH).move(x, y).radius(2)
    .fill(FILL[cat]).stroke({ color: '#9b9b9b', width: 1.2 }).css('cursor', 'pointer');
  var tg = textLayer.group();
  if (lines.length === 1) {
    tg.text(lines[0]).font(F(16, 'bold')).fill('#111').center(x + CW / 2, y + CH / 2);
  } else if (lines.length === 2) {
    tg.text(lines[0]).font(F(15, 'bold')).fill('#111').center(x + CW / 2, y + CH / 2 - 13);
    tg.text(lines[1]).font(F(15, 'bold')).fill('#111').center(x + CW / 2, y + CH / 2 + 13);
  }
  var c = { g: g, p: p, sym: sym, lines: lines, charge: charge, cat: cat, conf: conf, rect: rect, tg: tg };
  rect.on('mousemove', function (e) {
    showTooltip(sym + ' · group ' + g + ' · ' + (lines.length ? lines.join(' / ') : 'no common ion shown'), e);
  });
  rect.on('mouseleave', hideTooltip);
  rect.on('click', function () {
    state.selected = c; render();
    showPopup(sym + ' — Group ' + g + ', Period ' + p, popupBody(c));
  });
  cells.push(c);
}

PLAIN.forEach(function (r) { addCell(r[0], r[1], r[2], [], null, r[3], ''); });
LAB.forEach(function (r) { addCell(r[0], r[1], r[2], r[3], r[4], r[5], r[6] || ''); });

