/* ---------- helpers ---------- */
function wrap(s, n) {
  var w = String(s).split(' '), out = [], cur = '';
  w.forEach(function (t) {
    if ((cur + ' ' + t).trim().length > n) { out.push(cur); cur = t; }
    else cur = (cur ? cur + ' ' : '') + t;
  });
  if (cur) out.push(cur);
  return out;
}
function setRule(s) {
  var ls = wrap(s, 56);
  for (var i = 0; i < iRule.length; i++) iRule[i].text(ls[i] || '');
}
function inRegion(c) {
  var r = state.region;
  if (r === 'overview') return true;
  if (r === 'group1and2') return c.g <= 2;
  if (r === 'nonmetals') return c.g >= 15 && c.g <= 17;
  if (r === 'transition') return c.g >= 3 && c.g <= 12;
  if (r === 'nobleGases') return c.g === 18;
  return true;
}
function groupInfo(g) {
  if (g === 1) return { c: '+1', sub: 'Li, Na, K, Rb, Cs, Fr — alkali metals', conf: 'valence ns¹ → lose 1 e⁻', rule: 'Charge equals the group number: one valence s electron is lost and the ion takes the configuration of the noble gas in the row above.' };
  if (g === 2) return { c: '+2', sub: 'Be, Mg, Ca, Sr, Ba, Ra — alkaline earth metals', conf: 'valence ns² → lose 2 e⁻', rule: 'Charge again equals the group number: both valence s electrons are lost to reach the previous noble-gas configuration.' };
  if (g >= 3 && g <= 12) return { c: 'variable', sub: 'transition metals (d-block)', conf: '(n−1)d^x ns² → ns lost first', rule: 'Here the group-number rule breaks down. After the s electrons go, a variable number of d electrons can also be removed: Cr³⁺/Cr⁶⁺, Fe²⁺/Fe³⁺, Cu⁺/Cu²⁺, Au⁺/Au³⁺.' };
  if (g === 13) return { c: '+3 (Al³⁺)', sub: 'B, Al, Ga, In, Tl', conf: 'ns²np¹ → lose 3 e⁻', rule: 'Charge = group number − 10. Aluminium empties both the s and p valence orbitals to give Al³⁺.' };
  if (g === 14) return { c: '±4, mostly covalent', sub: 'C, Si, Ge, Sn, Pb', conf: 'ns²np² → shares electrons', rule: 'Group 14 sits exactly halfway, so gaining or losing four electrons is costly; these elements usually bond covalently instead of forming ions.' };
  if (g === 15) return { c: '3−', sub: 'N, P, As (Sb, Bi)', conf: 'ns²np³ → gain 3 e⁻', rule: 'Charge = 18 − group = 3−. Three added electrons complete the p subshell and reach the next noble gas.' };
  if (g === 16) return { c: '2−', sub: 'O, S, Se, Te', conf: 'ns²np⁴ → gain 2 e⁻', rule: 'Charge = 18 − group = 2−. Two added electrons complete the valence octet.' };
  if (g === 17) return { c: '1−', sub: 'F, Cl, Br, I, At — halogens', conf: 'ns²np⁵ → gain 1 e⁻', rule: 'Charge = 18 − group = 1−. A single added electron completes the octet, which is why halogens are such strong electron acceptors.' };
  return { c: 'no ion', sub: 'He, Ne, Ar, Kr, Xe, Rn — noble gases', conf: 'ns²np⁶ — full valence shell', rule: 'Group 18 forms no common ion. Every charge elsewhere in the table is just an element reaching the nearest one of these configurations.' };
}
function updateInfo() {
  var c = state.selected;
  if (c) {
    infoG.show();
    iTitle.text(c.sym + (c.lines.length ? '  →  ' + c.lines.join('  /  ') : '  →  no common ion'));
    iSub.text('Group ' + c.g + ' · Period ' + c.p + ' · ' + CATNAME[c.cat]);
    iConf.text('Configuration: ' + (c.conf || 'not shown'));
    setRule(ruleFor(c));
  } else if (state.sweepActive) {
    infoG.show();
    var gi = groupInfo(state.group);
    iTitle.text('Group ' + state.group + '  →  ' + gi.c);
    iSub.text(gi.sub);
    iConf.text(gi.conf);
    setRule(gi.rule);
  } else infoG.hide();
}
var TYPE_LEGEND = [
  [FILL.alk, 'Group 1 — alkali metals (+1)'],
  [FILL.alke, 'Group 2 — alkaline earth (+2)'],
  [FILL.d, 'Groups 3–12 — transition metals'],
  [FILL.pn, 'Groups 15–16 — nonmetals (3−, 2−)'],
  [FILL.hal, 'Group 17 — halogens (1−)'],
  [FILL.nob, 'Group 18 — noble gases (no ion)'],
  [FILL.w, 'Other main-group / no ion shown']
];
function chargeLegend() {
  return [
    [chargeFill(1), '+1 cation'],
    [chargeFill(2), '+2 cation'],
    [chargeFill(3), '+3 cation'],
    [chargeFill('var'), 'several charges (d-block)'],
    [chargeFill(-1), '1− anion'],
    [chargeFill(-2), '2− / 3− / 4− anion'],
    [chargeFill(0), 'no common ion']
  ];
}
function fillLegend() {
  var rows = (state.scheme === 'charge') ? chargeLegend() : TYPE_LEGEND;
  lgTitle.text(state.scheme === 'charge' ? 'Colored by ion charge' : 'Colored by element type');
  for (var i = 0; i < lgRows.length; i++) {
    lgRows[i].sw.fill(rows[i][0]);
    lgRows[i].tx.text(rows[i][1]);
  }
}

/* ---------- render ---------- */
function render() {
  cells.forEach(function (c) {
    c.rect.fill(state.scheme === 'charge' ? chargeFill(c.charge) : FILL[c.cat]);
    var on = inRegion(c);
    c.rect.opacity(on ? 1 : 0.18);
    c.tg.opacity(on ? 1 : 0.18);
    var sel = (state.selected === c);
    c.rect.stroke({ color: sel ? '#d62728' : '#9b9b9b', width: sel ? 3 : 1.2 });
  });
  fblockCells.forEach(function (f) {
    f.rect.fill(state.scheme === 'charge' ? chargeFill(3) : f.base);
  });
  if (state.sweepActive) {
    var r = bandRange(state.group);
    band.show();
    band.size(CW + 10, (r[1] - r[0]) * PYs + CH + 10).move(cx(state.group) - 5, cy(r[0]) - 5);
  } else band.hide();
  updateInfo();
  if (state.scheme === 'charge' || state.region !== 'overview') { fillLegend(); legendG.show(); }
  else legendG.hide();
}

/* ---------- controls ---------- */
function update_groupSweep(v) {
  state.group = v; state.sweepActive = true; state.selected = null; render();
}
function toggle_colorScheme(on) {
  state.scheme = on ? 'charge' : 'type'; render();
}
function set_regionTour(v) {
  state.region = v; state.selected = null;
  if (v !== 'overview') state.sweepActive = true;
  render();
}
function resetFig() { applyStep(0); }

