    tg.text(lines[0]).font(F(23, 'bold')).fill('#111').center(x + CW / 2, y + CH / 2);
  } else if (lines.length === 2) {
    tg.text(lines[0]).font(F(20, 'bold')).fill('#111').center(x + CW / 2, y + CH / 2 - 15);
    tg.text(lines[1]).font(F(20, 'bold')).fill('#111').center(x + CW / 2, y + CH / 2 + 15);
  }
  var c = { g: g, p: p, sym: sym, lines: lines, charge: charge, cat: cat, conf: conf, rect: rect, tg: tg };
  rect.on('mousemove', function (e) {
    showTooltip(sym + ' · group ' + g + ' · ' + (lines.length ? lines.join(' / ') : 'no common ion shown'), e);
  });
  rect.on('mouseleave', hideTooltip);
  rect.on('click', function () {
    state.selected = c; render();
    showPopup(sym + ' — Group ' + g + ', Period ' + p, popupBody(c));
  });
  cells.push(c);
}

PLAIN.forEach(function (r) { addCell(r[0], r[1], r[2], [], null, r[3], ''); });
LAB.forEach(function (r) { addCell(r[0], r[1], r[2], r[3], r[4], r[5], r[6] || ''); });

/* ---------- column highlight band ---------- */
var band = bandLayer.rect(CW + 10, CH + 10).move(cx(1) - 5, cy(1) - 5).radius(4)
  .fill({ color: '#ffb300', opacity: 0.22 }).stroke({ color: '#e08a00', width: 3.5 })
  .attr('pointer-events', 'none');
band.hide();
function bandRange(g) {
  if (g === 1 || g === 18) return [1, 7];
  if (g === 2 || g >= 13) return [2, 7];
  return [4, 7];
}

/* ---------- annotations ---------- */
annoLayer.text('Periodic Table of the Elements').font(F(30, 'bold')).fill('#111').center(665, 48);
annoLayer.text('Group').font(F(25, 'bold')).fill(BLUE).center(84, 88);
var perLbl = annoLayer.text('Period').font(F(25, 'bold')).fill(PURPLE);
perLbl.center(22, 66); perLbl.rotate(-90);

[1, 18].forEach(function (g) { annoLayer.text(String(g)).font(F(25, 'bold')).fill(BLUE).center(cx(g) + CW / 2, 120); });
[13, 14, 15, 16, 17].forEach(function (g) { annoLayer.text(String(g)).font(F(25, 'bold')).fill(BLUE).center(cx(g) + CW / 2, cy(2) - 20); });
for (var gg = 3; gg <= 12; gg++) { annoLayer.text(String(gg)).font(F(25, 'bold')).fill(BLUE).center(cx(gg) + CW / 2, cy(4) - 20); }
for (var pp = 1; pp <= 7; pp++) { annoLayer.text(String(pp)).font(F(25, 'bold')).fill(PURPLE).center(20, cy(pp) + CH / 2); }

/* red outline around the group-3 cells of periods 6 & 7 */
annoLayer.rect(CW + 10, PYs + CH + 10).move(cx(3) - 5, cy(6) - 5)
  .fill('none').stroke({ color: RED, width: 3.5 });

/* curved red arrow (with soft gray shadow) down to the f-block panel */
annoLayer.path('M181,636 C188,694 202,730 238,746').fill('none')
  .stroke({ color: '#c7c7c7', width: 8, linecap: 'round' });
annoLayer.path('M177,632 C184,690 198,726 234,742').fill('none')
  .stroke({ color: RED, width: 5, linecap: 'round' });
annoLayer.polygon('252,754 226,748 237,731').fill(RED);

/* detached f-block */
var FX = 238, FPITCH = 75, FCW = 67, FCH = 64, FR1 = 668, FR2 = 740;
annoLayer.rect(1064, 156).move(228, 660).fill('none').stroke({ color: '#8a8a8a', width: 5 });
var fblockCells = [];
for (var i = 0; i < 14; i++) {
  var r1 = rectLayer.rect(FCW, FCH).move(FX + i * FPITCH, FR1).fill(FILL.lan).stroke({ color: '#8a8a8a', width: 2 });
  var r2 = rectLayer.rect(FCW, FCH).move(FX + i * FPITCH, FR2).fill(FILL.act).stroke({ color: '#8a8a8a', width: 2 });
  fblockCells.push({ rect: r1, base: FILL.lan });
  fblockCells.push({ rect: r2, base: FILL.act });
  (function (a, b) {
    a.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Lanthanide (f-block) — usually 3+', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('Lanthanides (f-block)', 'These 14 elements are pulled out of period 6, group 3. Their 4f electrons are buried beneath the valence shell, so nearly all of them form the same 3+ ion regardless of column.'); });
    b.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Actinide (f-block) — commonly 3+', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup('Actinides (f-block)', 'These 14 elements belong in period 7, group 3. Filling 5f orbitals gives many of them a 3+ ion, though the early actinides (U, Np, Pu) show several charges.'); });
  })(r1, r2);
}
annoLayer.text('*').font(F(22, 'bold')).fill('#111').center(220, FR1 + 26);
annoLayer.text('**').font(F(22, 'bold')).fill('#111').center(216, FR2 + 26);

/* ---------- explanation panel (below the table; hidden in the plain view) ---------- */
var infoG = ptDraw.group().attr('pointer-events', 'none');
infoG.rect(760, 278).move(40, 852).radius(10).fill('#ffffff').stroke({ color: '#c3c9d1', width: 2 });
var iTitle = infoG.text('').font(F(30, 'bold')).fill('#111').move(64, 866);
var iSub = infoG.text('').font(F(22)).fill('#555').move(64, 908);
var iConf = infoG.text('').font(F(22, 'bold')).fill(BLUE).move(64, 940);
var iRule = [];
for (var k = 0; k < 5; k++) iRule.push(infoG.text('').font(F(22)).fill('#333').move(64, 978 + k * 28));
infoG.hide();

var legendG = ptDraw.group().attr('pointer-events', 'none');
legendG.rect(468, 278).move(824, 852).radius(10).fill('#ffffff').stroke({ color: '#c3c9d1', width: 2 });
var lgTitle = legendG.text('').font(F(23, 'bold')).fill('#111').move(848, 866);
var lgRows = [];
for (var m = 0; m < 7; m++) {
  lgRows.push({
    sw: legendG.rect(34, 22).move(848, 906 + m * 32).stroke({ color: '#9b9b9b', width: 1.2 }).fill('#fff'),
    tx: legendG.text('').font(F(20)).fill('#333').move(894, 901 + m * 32)
  });
}
legendG.hide();

/* ---------- helpers ---------- */
function wrap(s, n) {
  var w = String(s).split(' '), out = [], cur = '';
  w.forEach(function (t) {
    if ((cur + ' ' + t).trim().length > n) { out.push(cur); cur = t; }
    else cur = (cur ? cur + ' ' : '') + t;
  });
  if (cur) out.push(cur);
  return out;
}
function setRule(s) {
  var ls = wrap(s, 62);
  for (var i = 0; i < iRule.length; i++) iRule[i].text(ls[i] || '');
}
function inRegion(c) {
  var r = state.region;
  if (r === 'overview') return true;
  if (r === 'group1and2') return c.g <= 2;
  if (r === 'nonmetals') return c.g >= 15 && c.g <= 17;
  if (r === 'transition') return c.g >= 3 && c.g <= 12;
  if (r === 'nobleGases') return c.g === 18;
  return true;
}
function groupInfo(g) {
  if (g === 1) return { c: '+1', sub: 'Li, Na, K, Rb, Cs, Fr — alkali metals', conf: 'valence ns¹ → lose 1 e⁻', rule: 'Charge equals the group number: one valence s electron is lost and the ion takes the configuration of the noble gas in the row above.' };
  if (g === 2) return { c: '+2', sub: 'Be, Mg, Ca, Sr, Ba, Ra — alkaline earth metals', conf: 'valence ns² → lose 2 e⁻', rule: 'Charge again equals the group number: both valence s electrons are lost to reach the previous noble-gas configuration.' };
  if (g >= 3 && g <= 12) return { c: 'variable', sub: 'transition metals (d-block)', conf: '(n−1)dˣ ns² → the ns electrons leave first', rule: 'Here the group-number rule breaks down. After the s electrons go, a variable number of d electrons can also be removed: Cr³⁺/Cr⁶⁺, Fe²⁺/Fe³⁺, Cu⁺/Cu²⁺, Au⁺/Au³⁺.' };
  if (g === 13) return { c: '+3 (Al³⁺)', sub: 'B, Al, Ga, In, Tl', conf: 'ns²np¹ → lose 3 e⁻', rule: 'Charge = group number − 10. Aluminium empties both the s and p valence orbitals to give Al³⁺.' };
  if (g === 14) return { c: '±4, mostly covalent', sub: 'C, Si, Ge, Sn, Pb', conf: 'ns²np² → shares electrons', rule: 'Group 14 sits exactly halfway, so gaining or losing four electrons is costly; these elements usually bond covalently instead of forming ions.' };
  if (g === 15) return { c: '3−', sub: 'N, P, As (Sb, Bi)', conf: 'ns²np³ → gain 3 e⁻', rule: 'Charge = 18 − group = 3−. Three added electrons complete the p subshell and reach the next noble gas.' };
  if (g === 16) return { c: '2−', sub: 'O, S, Se, Te', conf: 'ns²np⁴ → gain 2 e⁻', rule: 'Charge = 18 − group = 2−. Two added electrons complete the valence octet.' };
  if (g === 17) return { c: '1−', sub: 'F, Cl, Br, I, At — halogens', conf: 'ns²np⁵ → gain 1 e⁻', rule: 'Charge = 18 − group = 1−. A single added electron completes the octet, which is why halogens are such strong electron acceptors.' };
  return { c: 'no ion', sub: 'He, Ne, Ar, Kr, Xe, Rn — noble gases', conf: 'ns²np⁶ — full valence shell', rule: 'Group 18 forms no common ion. Every charge elsewhere in the table is just an element reaching the nearest one of these configurations.' };
}
var TYPE_LEGEND = [
  [FILL.alk, 'Group 1 — alkali metals (+1)'],
  [FILL.alke, 'Group 2 — alkaline earth (+2)'],
  [FILL.d, 'Groups 3–12 — transition metals'],
  [FILL.pn, 'Groups 15–16 — nonmetals (3−, 2−)'],
  [FILL.hal, 'Group 17 — halogens (1−)'],
  [FILL.nob, 'Group 18 — noble gases (no ion)'],
  [FILL.w, 'Other main-group / no ion shown']
];
function chargeLegend() {
  return [
    [chargeFill(1), '+1 cation'],
    [chargeFill(2), '+2 cation'],
    [chargeFill(3), '+3 cation'],
    [chargeFill('var'), 'several charges (d-block)'],
    [chargeFill(-1), '1− anion'],
    [chargeFill(-2), '2− / 3− / 4− anion'],
    [chargeFill(0), 'no common ion']
  ];
}
function fillLegend() {
  var rows = (state.scheme === 'charge') ? chargeLegend() : TYPE_LEGEND;
  lgTitle.text(state.scheme === 'charge' ? 'Colored by ion charge' : 'Colored by element type');
  for (var i = 0; i < lgRows.length; i++) {
    lgRows[i].sw.fill(rows[i][0]);
    lgRows[i].tx.text(rows[i][1]);
  }
}
function updateInfo() {
  var c = state.selected;
  if (c) {
    infoG.show();
    iTitle.text(c.sym + (c.lines.length ? '  →  ' + c.lines.join('  /  ') : '  →  no common ion'));
    iSub.text('Group ' + c.g + ' · Period ' + c.p + ' · ' + CATNAME[c.cat]);
    iConf.text('Configuration: ' + (c.conf || 'not shown'));
    setRule(ruleFor(c));
    return true;
  }
  if (state.sweepActive) {
    infoG.show();
    var gi = groupInfo(state.group);
    iTitle.text('Group ' + state.group + '  →  ' + gi.c);
    iSub.text(gi.sub);
    iConf.text(gi.conf);
    setRule(gi.rule);
    return true;
  }
  infoG.hide();
  return false;
}

/* ---------- render ---------- */
function render() {
  cells.forEach(function (c) {
    c.rect.fill(state.scheme === 'charge' ? chargeFill(c.charge) : FILL[c.cat]);
    var on = inRegion(c);
    c.rect.opacity(on ? 1 : 0.18);
    c.tg.opacity(on ? 1 : 0.18);
    var sel = (state.selected === c);
    c.rect.stroke({ color: sel ? '#d62728' : '#9b9b9b', width: sel ? 3.5 : 1.4 });
  });
  fblockCells.forEach(function (f) {
    f.rect.fill(state.scheme === 'charge' ? chargeFill(3) : f.base);
  });
  if (state.sweepActive) {
    var r = bandRange(state.group);
    band.show();
    band.size(CW + 10, (r[1] - r[0]) * PYs + CH + 10).move(cx(state.group) - 5, cy(r[0]) - 5);
  } else band.hide();

  var showInfo = updateInfo();
  var showLeg = (state.scheme === 'charge' || state.region !== 'overview' || state.sweepActive || !!state.selected);
  if (showLeg) { fillLegend(); legendG.show(); } else legendG.hide();

  ptDraw.viewbox(0, 0, PW, (showInfo || showLeg) ? H_TALL : H_SHORT);
}

/* ---------- controls ---------- */
function update_groupSweep(v) {
  state.group = v; state.sweepActive = true; state.selected = null; render();
}
function toggle_colorScheme(on) {
  state.scheme = on ? 'charge' : 'type'; render();
}
function set_regionTour(v) {
  state.region = v; state.selected = null;
  if (v !== 'overview') state.sweepActive = true;
  render();
}
function resetFig() { applyStep(0); }

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'The whole table', narration: 'Every cell carrying a charge label is colored by element type: purple and green metals on the left, pink and lavender nonmetals on the right, tan transition metals in the middle, cyan noble gases with no label at all.', state: { regionTour: 'overview', colorScheme: 'Element type', groupSweep: 1 }, sweep: false },
  { title: 'Groups 1 & 2: charge = group number', narration: 'Sweeping the slider to group 1 highlights Li⁺ through Fr⁺, all +1; group 2 gives Be²⁺ through Ra²⁺, all +2. Metals lose their few valence s electrons, so the charge simply equals the group number.', state: { regionTour: 'group1and2', colorScheme: 'Element type', groupSweep: 2 }, sweep: true },
  { title: 'Groups 15–17: counting back from the noble gas', narration: 'On the right, nonmetals gain electrons instead: group 17 forms 1− ions, group 16 forms 2−, group 15 forms 3− — the negative charge equals how many columns the element sits to the left of group 18.', state: { regionTour: 'nonmetals', colorScheme: 'Element type', groupSweep: 16 }, sweep: true },
  { title: 'The d-block exception', narration: 'In the tan transition-metal block a single element can show more than one charge — Cr³⁺ and Cr⁶⁺, Fe²⁺ and Fe³⁺, Cu⁺ and Cu²⁺, Au⁺ and Au³⁺ — so group position alone no longer predicts the ion.', state: { regionTour: 'transition', colorScheme: 'Element type', groupSweep: 8 }, sweep: true },
  { title: 'Noble gases: no charge', narration: 'Group 18 cells carry only element symbols. With filled valence shells there is no energetic reason to gain or lose electrons, which is why the rest of the table\u2019s charges are all measured against them.', state: { regionTour: 'nobleGases', colorScheme: 'Element type', groupSweep: 18 }, sweep: true },
  { title: 'Recolor by charge', narration: 'Switching to charge-value coloring redraws the same table by ion charge. The cation/anion divide falls exactly on the metal/nonmetal divide — two different classifications, one underlying boundary.', state: { regionTour: 'overview', colorScheme: 'Charge value', groupSweep: 1 }, sweep: true }
];
var curStep = 0;
function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep];
  document.getElementById('groupSweepInput').value = s.state.groupSweep;
  document.getElementById('groupSweepVal').value = s.state.groupSweep;
  document.getElementById('colorSchemeInput').checked = (s.state.colorScheme === 'Charge value');
  document.getElementById('regionTourInput').value = s.state.regionTour;
  state.group = s.state.groupSweep;
  state.scheme = (s.state.colorScheme === 'Charge value') ? 'charge' : 'type';
  state.region = s.state.regionTour;
  state.sweepActive = !!s.sweep;
  state.selected = null;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + STEPS.length + ' · ' + s.title;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: An element's column in the periodic table predicts the charge of the monatomic ion it forms: main-group metals lose electrons to become 1+, 2+ or 3+ cations and nonmetals gain electrons to become 3−, 2− or 1− anions, all reaching the nearest noble-gas electron count.
KEY INSIGHT (what students should walk away understanding): Ionic charge is read off the column, not memorized element by element: each main-group atom gains or loses the smallest number of electrons that leaves it with a noble-gas electron count, so the charge mirrors the distance to group 18.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "An element's column in the periodic table predicts the charge of the monatomic ion it forms: main-group metals lose electrons to become 1+, 2+ or 3+ cations and nonmetals gain electrons to become 3−, 2− or 1− anions, all reaching the nearest noble-gas electron count.",
  "figureType": "diagram",
  "elements": [
    "Standard periodic table outline: 18 columns × 7 rows of square cells with thin gray borders and the usual gaps (period 1 has only the far-left and far-right cells; periods 2–3 omit the d-block columns)",
    "Element symbol printed in each cell in plain black type (atomic number optional, small, above the symbol)",
    "Two detached rows of 14 cells below the main grid for the lanthanides and actinides, same cell style, left unshaded",
    "Group numbers 1–18 in small black type above the columns",
    "Charge banner boxes sitting directly above the colored columns, each reading the ionic charge for that column: '1+' over group 1, '2+' over group 2, '3+' over group 13, '3−' over group 15, '2−' over group 16, '1−' over group 17",
    "Colored column fills: group 1, group 2, group 13, group 15, group 16, group 17 each filled with their own pastel hue; each charge banner box uses exactly the same fill as the column it labels",
    "Group 18 column filled pale gray and labeled 'noble gases — no ions formed'",
    "Transition-metal block (groups 3–12) left white/unshaded with a caption noting that these metals form more than one possible charge",
    "Group 14 column left white/unshaded (does not follow a single simple rule)",
    "Hydrogen cell in group 1 left unshaded or visibly distinguished, since it is not an alkali metal",
    "Figure caption line beneath the table: 'Elements in the same group form ions of the same charge.'",
    "Translucent highlight band drawn over whichever column the learner sweeps or selects",
    "Side info panel (interactive overlay, not part of the printed figure) showing the selected element's symbol, group, ion formula, electrons lost or gained, and the noble gas it matches"
  ],
  "interactions": [
    {
      "id": "groupSweep",
      "type": "slider",
      "label": "Group number",
      "range": [
        1,
        18,
        1
      ],
      "default": 1,
      "teaches": "That ionic charge is a property of the whole column: sweeping left to right gives 1+, 2+, then the unpredictable transition metals, then 3+, no rule, 3−, 2−, 1−, and finally zero.",
      "default_note": null
    },
    {
      "id": "elementClick",
      "type": "click",
      "teaches": "That a single element's charge comes from counting electrons to the nearest noble gas — clicking Na shows it loses one electron to match Ne, clicking S shows it gains two to match Ar.",
      "default_note": null
    },
    {
      "id": "regionTour",
      "type": "state",
      "label": "Guided regions",
      "states": [
        "overview",
        "cations",
        "anions",
        "transitionMetals",
        "nobleGases"
      ],
      "default": "overview",
      "teaches": "Where the group-number rule works and where it fails, by visiting the cation columns, the anion columns, the multi-charge d-block, and the inert noble gases in turn."
    }
  ],
  "demo_steps": [
    {
      "title": "The whole table",
      "narration": "Six columns of the periodic table are colored, and above each sits a charge banner: 1+, 2+, 3+ on the left and 3−, 2−, 1− on the right. Every element inside a colored column forms an ion of that charge.",
      "state": {
        "regionTour": "overview",
        "groupSweep": 1
      }
    },
    {
      "title": "Metals on the left lose electrons",
      "narration": "Group 1 is highlighted: every member forms a 1+ ion. Step to group 2 and every member forms 2+; group 13 gives 3+. The positive charge equals the number of valence electrons the metal gives away.",
      "state": {
        "regionTour": "cations",
        "groupSweep": 2
      }
    },
    {
      "title": "Nonmetals on the right gain electrons",
      "narration": "Group 17 forms 1− ions, group 16 forms 2−, group 15 forms 3−. The negative charge equals how many columns the element sits to the left of the noble gases — the number of electrons it must pick up.",
      "state": {
        "regionTour": "anions",
        "groupSweep": 16
      }
    },
    {
      "title": "The uncolored middle",
      "narration": "The transition metals in groups 3–12, and group 14, are deliberately left uncolored with no charge banner: these elements form more than one possible ion, so column position alone does not predict the charge.",
      "state": {
        "regionTour": "transitionMetals",
        "groupSweep": 8
      }
    },
    {
      "title": "Noble gases: the reference point",
      "narration": "Group 18 is gray and carries no charge. Its filled valence shell is the target every other ion is aiming for, which is exactly why the charges rise 1+, 2+, 3+ moving away from it on one side and fall 3−, 2−, 1− approaching it on the other.",
      "state": {
        "regionTour": "nobleGases",
        "groupSweep": 18
      }
    }
  ],
  "keyInsight": "Ionic charge is read off the column, not memorized element by element: each main-group atom gains or loses the smallest number of electrons that leaves it with a noble-gas electron count, so the charge mirrors the distance to group 18.",
  "reconstructionNotes": "Draw a clean, standard periodic table: 18 columns, 7 rows, square cells with thin gray borders, the usual empty gaps, plus two detached 14-cell rows (lanthanides/actinides) beneath, left unshaded. Each cell holds only its element symbol in black; no per-cell charge labels. The charge information lives in banner boxes above the columns — '1+' above group 1, '2+' above group 2, '3+' above group 13, '3−' above group 15, '2−' above group 16, '1−' above group 17 — and each banner box is filled with the SAME pastel color as the column beneath it, so color is the link between banner and column. Use six distinct soft pastels (for example pale blue, pale green, pale yellow, pale orange, pale pink, pale violet) applied consistently and lightly enough that black symbols stay readable; group 18 is pale gray labeled 'noble gases'; groups 3–12 and group 14 stay white with no banner. Do not invent extra decorations: no red outline boxes, no curved arrows, no per-element multi-charge lists such as Cr6+ or Hg2^2+, no legend of element types. Column highlighting for the interaction should be a translucent amber overlay with a bold outline; the click info panel sits to the right of the table showing symbol, group, ion formula, electrons lost/gained, and the matching noble gas."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.
